import{_ as a,C as r,o as l,c as d,a2 as i,E as s,j as t,a as o}from"./chunks/framework.CGSzHL4z.js";const b=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1792705540000}'),c={name:"guide/installation.md"};function u(h,e,g,p,m,w){const n=r("Screenshot");return l(),d("div",null,[e[0]||(e[0]=i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="the-plugin" tabindex="-1">The plugin <a class="header-anchor" href="#the-plugin" aria-label="Permalink to &quot;The plugin&quot;">​</a></h2><p>Get AcesMotion from the Creator Store: <a href="https://create.roblox.com/store/asset/108839243533841" target="_blank" rel="noreferrer">https://create.roblox.com/store/asset/108839243533841</a>. Click <strong>Get</strong>, then open Studio&#39;s <strong>Plugins</strong> tab. When a new version is out, Studio&#39;s <strong>Manage Plugins</strong> shows an <strong>Update</strong> button, and AcesMotion tells you too (Settings &gt; Versions).</p><h3 id="how-to-open-it" tabindex="-1">How to open it <a class="header-anchor" href="#how-to-open-it" aria-label="Permalink to &quot;How to open it&quot;">​</a></h3><ul><li>The plugin adds one toolbar named <strong>AcesMotion</strong> with one button. Its tooltip is &quot;Turn AcesMotion on or off&quot;.</li><li>Click the button: the Timeline, Hub and the Inspector open, and the scene that was open last reopens. Click it again: every AcesMotion window closes. The button shows as on (lit) while any AcesMotion window is open, so a click with only the Inspector open closes it too.</li><li><strong>The Timeline is the switch for the scene.</strong> Hiding the Timeline any way (its own close button, the toolbar button) closes the open scene and puts every stand-in back at rest. Showing the Timeline again reopens that scene. Resetting the window layout does not close the scene.</li><li>The other windows open from the Timeline&#39;s View &gt; Windows menu: Hub, Inspector, Settings. Settings also opens from the Scene menu&#39;s Settings item, from the Settings button on the empty Timeline, and from any &quot;... settings...&quot; menu item. The shortcut &quot;Open settings&quot; has no default key.</li><li>First placement: the Timeline docks at the bottom, Hub and the Inspector dock on the right (the Inspector opens under Hub), and Settings floats. After that Studio remembers where you put each window. <strong>View &gt; Windows &gt; Reset window layout</strong> (shortcut &quot;Reset window layout&quot;, no default key) puts them back at Studio&#39;s first placement.</li><li>Window titles read &quot;AcesMotion 0.2.0 · Timeline&quot;, &quot;... · Hub&quot;, &quot;... · Inspector&quot;, &quot;... · Settings&quot;.</li></ul>',5)),s(n,{name:"toolbar-button",caption:"The AcesMotion toolbar button."}),e[1]||(e[1]=i('<h2 id="the-runtime" tabindex="-1">The runtime <a class="header-anchor" href="#the-runtime" aria-label="Permalink to &quot;The runtime&quot;">​</a></h2><p>Games play scenes with the runtime, a ModuleScript the plugin writes into your place.</p><h3 id="install-and-layout" tabindex="-1">Install and layout <a class="header-anchor" href="#install-and-layout" aria-label="Permalink to &quot;Install and layout&quot;">​</a></h3><ul><li>Settings &gt; About &gt; <strong>Install runtime</strong> (or <strong>Update runtime</strong>, also on the Timeline&#39;s &quot;Update runtime&quot; banner) writes the module <code>ReplicatedStorage.AcesMotion</code> from the plugin itself: a ModuleScript (its source is a short note, the MIT licence, and a <code>require</code>) holding <code>Engine</code>, <code>Runtime</code> and <code>Packages</code> (Signal, Trove), with an <code>AcesMotion_Version</code> attribute. Updating keeps the root and replaces its children; scenes are untouched; one undo step. A place whose runtime is synced from files refuses the button. About shows &quot;Not installed&quot;, &quot;0.2.0 (up to date)&quot;, &quot;(older, update it)&quot; or &quot;(newer than this plugin)&quot;.</li><li><code>local AcesMotion = require(game.ReplicatedStorage.AcesMotion)</code>. <strong>Every client requires it once</strong> to receive <code>PlayForAll</code> (a LocalScript in StarterPlayerScripts is enough). Requiring it on the server is <strong>optional</strong>: only <code>PlayForAll</code> and a server <code>Play</code> need it there (a client-only game never touches the server).</li><li>Scenes are found by name in <code>ReplicatedStorage.AcesMotionScenes</code>, then in every folder given to <code>RegisterFolder</code> (subfolders too, shallowest first, never inside a scene). A client can only play scenes it can see (not ServerStorage). Register the folder on every side that plays by name.</li><li><strong>Custom generators</strong>: ModuleScripts tagged <code>AcesMotionGenerator</code> (anywhere both sides can require) register by module name and keep working after a rename; a generator the game can&#39;t find adds nothing (warned once).</li><li><strong>Custom constraints</strong>: ModuleScripts tagged <code>AcesMotionConstraint</code> (anywhere both sides can require) register by module name and keep working after a rename; a constraint the game can&#39;t find does nothing, and one that doesn&#39;t load warns once.</li><li><strong>Custom actions</strong>: ModuleScripts tagged <code>AcesMotionAction</code> (anywhere) register by module name; a module may return just a function (an instant action); <code>RegisterAction</code> also works for action blocks with that <code>Action</code> (run only where the scene plays in full). <strong>Modifiers</strong>: <code>ReplicatedStorage.AcesMotionModifiers</code> (stored; not evaluated yet).</li><li><code>AcesMotion.Version</code> is the release version; <code>AcesMotion.FormatVersion</code> is the newest scene format it reads. A scene saved in a newer format is refused by name.</li></ul>',4)),s(n,{name:"install-runtime",caption:"Settings > About: the runtime in this place and the button that installs or updates it."}),e[2]||(e[2]=t("p",null,[o("The full API, with every function, option and type, is in the "),t("a",{href:"/AcesMotion-docs/api/"},"Runtime API"),o(".")],-1)),e[3]||(e[3]=t("p",null,[t("strong",null,"Next:"),o(),t("a",{href:"./tour"},"A quick tour"),o(" of the windows.")],-1))])}const y=a(c,[["render",u]]);export{b as __pageData,y as default};
